corrected_code:
import { json, LoaderFunctionArgs } from '@remix-run/node';
import BookmarkModel from '~/models/Bookmark.server';
import { getUserIdFromSession } from '~/session.server';

export async function loader({ request, params }: LoaderFunctionArgs) {
  const userId = await getUserIdFromSession(request);
  if (!userId) throw new Response('Login required', { status: 401 });

  const bookmark = await BookmarkModel.findOne({
    _id: params.bookmarkId,
    userId: userId,
  });
  if (!bookmark) throw new Response('Forbidden or Not Found', { status: 403 });

  return json({ bookmark });
}
